# Tiap soal: (pertanyaan, jawaban benar, [pilihan salah], penjelasan, rujukan hlm)
# SMP: 2 salah (3 pilihan). Dewasa: 3 salah (4 pilihan). Urutan diacak saat build.
ST=[
# 1 Jazirah Arab sebelum risalah
{'s':[
 ("Siapa yang membawa berhala Hubal dari Syam dan meletakkannya di dalam Ka’bah?",
  "Amr bin Luhay dari Bani Khuza’ah",["Qushay bin Kilab dari Bani Quraisy", "Abdul Muththalib dari Bani Hasyim"],
  "Amr bin Luhay melihat penduduk Syam menyembah berhala dan menganggapnya baik. Sepulang dari sana ia membawa Hubal ke Ka’bah dan mengajak penduduk Makkah menyekutukan Allah.","hlm. 23"),
 ("Berapa jumlah berhala di sekitar Ka’bah ketika Nabi menaklukkan Makkah?",
  "360",["300", "630"],
  "Buku menyebut ada 360 berhala di sekitar Ka’bah. Rasulullah menghancurkannya, lalu memerintahkan agar berhala itu dikeluarkan dari masjid dan dibakar.","hlm. 24")],
 'd':[
 ("Menurut buku, bagaimana Abrahah menjadi penguasa Yaman?",
  "Ia membunuh Aryath, panglima Habasyah, lalu menggantikannya",["Ia menggulingkan Dzu Nuwas dan langsung dilantik raja Habasyah", "Ia menggantikan Aryath yang wafat karena sakit di Shan’a", "Ia diangkat Kisra Persia setelah Aryath mengundurkan diri"],
  "Sebanyak 70.000 pasukan Habasyah menguasai Yaman untuk kedua kalinya di bawah Aryath pada 525 M. Aryath dibunuh anak buahnya, Abrahah, yang lalu menggantikannya.","hlm. 12"),
 ("Siapa yang dijadikan hakim perdamaian antara Qushay dan Bani Khuza’ah, dan apa putusannya?",
  "Ya’mar bin Auf dari Bani Bakr; Qushay lebih berhak mengurus Ka’bah",["Hulail bin Hubsyah dari Khuza’ah; Ka’bah tetap diurus Khuza’ah", "Abdul Muththalib dari Bani Hasyim; Ka’bah diurus bergantian", "Ya’mar bin Auf dari Bani Bakr; Ka’bah dibagi dua kubu"],
  "Setelah perang dahsyat kedua pihak sepakat berdamai. Ya’mar bin Auf menetapkan bahwa Qushay lebih layak menangani urusan Ka’bah dan berkuasa di Makkah daripada Bani Khuza’ah.","hlm. 18")]},
# 2 Kelahiran dan 40 tahun sebelum nubuwah
{'s':[
 ("Setelah ibundanya, siapa wanita pertama yang menyusui Nabi?",
  "Tsuwaibah, hamba sahaya Abu Lahab",["Halimah dari Bani Sa’d, di pedesaan", "Ummu Aiman, pengasuh beliau di Makkah"],
  "Tsuwaibah menyusui beliau, setelah sebelumnya menyusui Hamzah. Sesudah itu beliau tinggal di tengah Bani Sa’d, mengikuti tradisi Arab menyusukan bayi di pedesaan.","hlm. 49"),
 ("Pada usia berapa Nabi berdagang ke Syam membawa barang dagangan Khadijah?",
  "25 tahun",["12 tahun", "30 tahun"],
  "Pada usia 25 tahun beliau menjalankan dagangan Khadijah ke Syam. Perjalanan ke Syam pada usia 12 tahun adalah bersama Abu Thalib, tempat beliau bertemu rahib Bahira di Bushra.","hlm. 54, 56")],
 'd':[
 ("Menurut buku, apa yang menimpa Abrahah setelah pasukannya dibinasakan di sekitar Makkah?",
  "Sendi tulangnya lepas satu per satu, dan ia mati setibanya di Shan’a",["Ia tewas dilempari batu di Wadi Muhassir bersama pasukannya", "Ia lari ke Habasyah dan wafat di sana karena sakit", "Ia terbunuh oleh pasukannya sendiri saat mundur ke Yaman"],
  "Allah mengirim penyakit kepadanya hingga sendi-sendinya lepas. Setibanya di Shan’a dadanya terbelah dan ia mati. Peristiwa ini terjadi pada Muharram, 50 atau 55 hari sebelum kelahiran Nabi.","hlm. 45"),
 ("Nabi bersabda, “Aku adalah anak dua orang yang disembelih.” Siapa dua orang itu?",
  "Isma’il dan Abdullah",["Isma’il dan Ishaq", "Ibrahim dan Isma’il", "Abdullah dan Abdul Muththalib"],
  "Abdul Muththalib bernazar akan mengorbankan salah seorang dari sepuluh putranya jika Allah memberinya anak sebanyak itu. Undian jatuh pada Abdullah, lalu ia ditebus dengan seratus ekor unta.","hlm. 44, 47")]},
# 3 Gua Hira
{'s':[
 ("Setelah menerima wahyu pertama, kepada siapa Nabi pulang dan meminta, “Selimutilah aku”?",
  "Khadijah binti Khuwailid, istri beliau",["Abu Thalib bin Abdul Muththalib", "Abu Bakar Ash-Shiddiq"],
  "Beliau pulang dengan hati bergetar menemui Khadijah dan minta diselimuti sampai tubuhnya berhenti menggigil.","hlm. 64"),
 ("Apa yang dibawa Nabi sebagai bekal saat menyendiri di Gua Hira?",
  "Roti dari gandum dan air",["Daging kering dan anggur", "Korma dan susu kambing"],
  "Menjelang usia 40 tahun beliau gemar menyendiri. Beliau membawa roti gandum dan air ke Gua Hira di Jabal Nur, sekitar dua mil dari Makkah.","hlm. 61")],
 'd':[
 ("Wahyu yang datang menyerupai bunyi gemerincing lonceng digambarkan sebagai tingkatan wahyu yang…",
  "Paling berat; dahi beliau berkeringat meski cuaca dingin",["Paling ringan; hanya berupa bisikan dalam hati yang tenang", "Jibril datang dalam rupa manusia dan berbicara kepada beliau", "Wahyu yang diterima lewat mimpi saat beliau tidur"],
  "Dalam tingkatan ini malaikat tidak terlihat oleh Nabi. Dahi beliau berkerut dan berkeringat sekalipun pada waktu yang sangat dingin, dan hewan tunggangan beliau menderum ke tanah.","hlm. 68"),
 ("Setelah menenangkan Nabi dengan menyebut sifat-sifat beliau, Khadijah membawa beliau menemui siapa?",
  "Waraqah bin Naufal, anak paman Khadijah yang Nashrani",["Umayyah bin Ash-Shallat, penyair penganut hanif", "Abu Thalib, paman beliau yang mengasuh beliau sejak kecil", "Bahira, rahib yang pernah beliau temui di Bushra"],
  "Khadijah berkata Allah tidak akan menghinakan beliau karena beliau menyambung silaturahim, memikul beban orang lain, memberi makan orang miskin, menjamu tamu, dan menolong yang menegakkan kebenaran. Waraqah lalu menyatakan beliau benar-benar nabi umat ini.","hlm. 64–66")]},
# 4 Dakwah sembunyi
{'s':[
 ("Berapa lama dakwah secara sembunyi-sembunyi berlangsung?",
  "Tiga tahun",["Satu tahun", "Lima tahun"],
  "Buku menyebut tiga tahun dakwah sembunyi-sembunyi, dimulai kepada orang-orang terdekat.","hlm. 73"),
 ("Pada awal Islam, shalat yang diwajibkan dikerjakan bagaimana, menurut Muqatil bin Sulaiman?",
  "Dua rakaat pagi dan dua rakaat petang",["Empat rakaat pada pagi hari saja", "Dua rakaat setiap tengah malam"],
  "Perintah shalat termasuk wahyu yang pertama turun. Pada awal Islam shalat dikerjakan dua rakaat pagi dan dua rakaat petang.","hlm. 75")],
 'd':[
 ("Mengapa Quraisy pada awalnya tidak begitu peduli terhadap dakwah Nabi?",
  "Mereka mengira beliau hanya salah satu pembicara soal ketuhanan",["Karena Abu Jahal sudah menjamin dakwah itu tidak berbahaya bagi Quraisy", "Karena dakwah itu hanya disampaikan di luar Makkah", "Karena sebagian besar pemuka Quraisy sudah masuk Islam"],
  "Kabar dakwah memang menyebar di kalangan Quraisy, tetapi mereka menganggapnya urusan agama biasa, sampai dakwah mulai menyentuh berhala dan kepemimpinan mereka.","hlm. 76"),
 ("Mengapa seruan Abu Bakar didengar orang-orang Quraisy yang biasa duduk bersamanya?",
  "Ia berpengetahuan, ramah, dan sukses berdagang",["Ia pemuka Bani Hasyim yang paling kaya dan disegani", "Ia pemegang kunci Ka’bah dan penjaga sumur Zamzam", "Ia pemimpin pasukan Quraisy yang paling berani"],
  "Abu Bakar lemah lembut, pengasih, dan berakhlak mulia. Berkat seruannya masuk Islam Utsman bin Affan, Az-Zubair, Abdurrahman bin Auf, Sa’d bin Abi Waqqash, dan Thalhah bin Ubaidillah.","hlm. 74")]},
# 5 Dakwah terang-terangan
{'s':[
 ("Rasulullah menjuluki Umar bin Al-Khaththab setelah ia masuk Islam. Apa julukannya?",
  "Al-Faruq",["Ash-Shiddiq", "Saifullah"],
  "“Al-Faruq” berarti yang memisahkan antara yang haq dan yang batil. Ibnu Mas’ud berkata, hampir-hampir kaum Muslimin tidak bisa shalat di dekat Ka’bah sebelum Umar masuk Islam.","hlm. 115"),
 ("Siapa yang membeli Bilal bin Rabbah dari penyiksanya lalu memerdekakannya?",
  "Abu Bakar Ash-Shiddiq",["Utsman bin Affan", "Ali bin Abu Thalib"],
  "Para budak yang masuk Islam disiksa dengan keras. Abu Bakar membeli Bilal, lalu memerdekakannya.","hlm. 95")],
 'd':[
 ("Siapa utusan Quraisy kepada Najasyi, dan apa yang mereka bawa?",
  "Amr bin Al-Ash dan Abdullah bin Abu Rabi’ah, membawa hadiah",["Abu Jahal dan Utbah bin Rabi’ah, membawa surat Abu Thalib", "Abu Sufyan dan Al-Walid bin Al-Mughirah, membawa uang tebusan", "Utbah dan Syaibah bin Rabi’ah, membawa kuda terbaik"],
  "Quraisy memilih dua orang terpandang dan cerdik yang saat itu belum masuk Islam. Mereka lebih dulu menemui para uskup dengan hadiah, lalu menghadap Najasyi.","hlm. 101"),
 ("Apa tawaran kompromi Al-Aswad, Al-Walid bin Al-Mughirah, dan Al-Ash bin Wa’il kepada Nabi ketika beliau thawaf?",
  "Bergantian menyembah: mereka menyembah yang beliau sembah dan sebaliknya",["Beliau diberi harta dan istri tercantik di Makkah", "Beliau diangkat menjadi raja Makkah asal berhenti berdakwah", "Mereka mau menyembah Allah asal beliau berhenti mencela berhala dan sesembahan mereka"],
  "Mereka menawarkan persekutuan dalam peribadatan. Tawaran harta dan kedudukan datang dari tokoh lain, Utbah bin Rabi’ah, pada kesempatan terpisah.","hlm. 88, 116")]},
# 6 Pemboikotan dan Tahun Berduka
{'s':[
 ("Apa yang ditemukan pada piagam pemboikotan sebelum dirobek?",
  "Rayap memakan isinya, kecuali bagian yang memuat nama Allah",["Isinya luntur hingga tak bisa dibaca sama sekali", "Piagam itu terlepas dari dinding Ka’bah dan hilang"],
  "Al-Muth’im bangkit hendak merobek piagam dan mendapati isinya dimakan rayap, kecuali penggalan “Bismika Allahumma” dan bagian yang memuat kata “Allah”. Boikot pun dibatalkan.","hlm. 123"),
 ("Siapa yang diam-diam membawa makanan kepada Bani Hasyim pada malam hari selama pemboikotan?",
  "Hisyam bin Amr dari Bani Amir bin Luway",["Zuhair bin Abu Umayyah dari Bani Makhzum", "Al-Muth’im bin Adi dari Bani Naufal"],
  "Hisyam biasa menemui Bani Hasyim malam hari membawa makanan. Ia lalu menggerakkan beberapa tokoh Quraisy, termasuk Zuhair bin Abu Umayyah, untuk membatalkan piagam.","hlm. 121–122")],
 'd':[
 ("Apa yang Nabi sabdakan tentang gangguan Quraisy setelah Abu Thalib wafat?",
  "Gangguan yang paling beliau benci baru terjadi setelah Abu Thalib wafat",["Gangguan terberat justru terjadi saat boikot, bukan sesudahnya", "Gangguan Quraisy berkurang karena orang yang paling mereka segani telah tiada", "Gangguan baru terjadi setelah beliau hijrah ke Madinah"],
  "Karena penderitaan yang bertumpuk pada tahun itu, beliau menyebutnya ‘Amul-huzni (tahun duka cita).","hlm. 130"),
 ("Kapan Nabi menikahi Saudah?",
  "Syawwal tahun ke-10 nubuwah",["Syawwal tahun ke-3 nubuwah", "Dzul-Qa’dah tahun ke-10 nubuwah", "Syawwal tahun 1 H"],
  "Pernikahan itu terjadi sesudah wafatnya Abu Thalib dan Khadijah, pada Syawwal tahun kesepuluh dari nubuwah.","hlm. 130")]},
# 7 Thaif dan Isra' Mi'raj
{'s':[
 ("Di Qarnuts-Tsa’alib, malaikat penjaga gunung menawarkan meratakan Akhsyabain. Apa jawaban Nabi?",
  "Beliau berharap kelak lahir dari mereka orang yang menyembah Allah",["Beliau menyetujui agar kaum Thaif dihancurkan saat itu juga", "Beliau menolak dan meminta malaikat itu pergi dari Thaif"],
  "Setelah ditolak di Thaif beliau pergi dengan muka muram. Allah mengutus malaikat penjaga gunung, tetapi beliau memilih berharap kepada keturunan mereka kelak.","hlm. 144"),
 ("Dalam Isra’ Mi’raj Nabi ditawari susu dan khamr. Mana yang beliau pilih?",
  "Susu",["Air Zamzam", "Khamr"],
  "Beliau ditawari susu dan khamr, lalu memilih susu.","hlm. 161")],
 'd':[
 ("Siapa yang memberi jaminan perlindungan kepada Nabi ketika kembali ke Makkah dari Thaif?",
  "Al-Muth’im bin Adi, yang bersiaga bersama anak-anaknya",["Abu Jahal bin Hisyam, tokoh Bani Makhzum yang paling disegani", "Abu Sufyan bin Harb, pemuka Bani Umayyah", "Abu Lahab, paman beliau dari Bani Hasyim"],
  "Abu Jahal hanya menyatakan akan melindungi siapa pun yang dilindungi Muth’im. Rasulullah terus mengenang jasa ini. Pada tawanan Badr beliau bersabda andai Muth’im masih hidup dan memintanya, beliau akan menyerahkan urusan mereka kepadanya.","hlm. 147"),
 ("Setelah shalat diwajibkan lima puluh kali, siapa yang menyarankan Nabi kembali memohon keringanan?",
  "Musa",["Ibrahim", "Isa", "Jibril"],
  "Musa berkata umat beliau tidak akan sanggup, lalu menyuruh beliau kembali kepada Rabb-nya untuk meminta keringanan.","hlm. 160")]},
# 8 Baiat Aqabah
{'s':[
 ("Siapa duta Islam pertama yang diutus Nabi ke Yastrib setelah Baiat Aqabah pertama?",
  "Mush’ab bin Umair",["Abu Bakar Ash-Shiddiq", "Ali bin Abu Thalib"],
  "Mush’ab, pemuda yang termasuk pendahulu masuk Islam, diutus mengajarkan syariat dan berdakwah. Ia menginap di rumah As’ad bin Zurarah.","hlm. 166"),
 ("Berapa orang yang hadir pada Baiat Aqabah kedua?",
  "73 laki-laki dan 2 wanita",["70 laki-laki dan 5 wanita", "73 laki-laki tanpa wanita"],
  "Mereka keluar diam-diam dari rombongan setelah lewat sepertiga malam dan berkumpul di bukit Aqabah. Dua wanita itu Nasibah binti Ka’b (Ummu Ammarah) dan Asma binti Amr (Ummu Mani’).","hlm. 171")],
 'd':[
 ("Seluruh perkampungan Bani Abdil-Asyhal masuk Islam dalam sehari kecuali satu orang yang menangguhkan keislamannya hingga Perang Uhud. Siapa dia?",
  "Al-Ushairim",["Usaid bin Hudhair", "Sa’d bin Mu’adz", "Abdullah bin Ubay"],
  "Al-Ushairim masuk Islam saat Perang Uhud, ikut berperang, dan gugur sebagai syahid sebelum pernah shalat. Nabi bersabda, “Dia mengerjakan yang sedikit namun mendapat pahala yang melimpah.”","hlm. 168–169"),
 ("Mengapa Al-Muth’im bin Adi dan Al-Harits bin Harb membebaskan Sa’d bin Ubadah dari siksaan Quraisy?",
  "Sa’d pernah menjamin keamanan kafilah dagang mereka di Madinah",["Sa’d lebih dulu membebaskan tawanan Quraisy di Yastrib", "Sa’d adalah kerabat dekat mereka dari pihak ibu, tinggal di Makkah", "Sa’d bersedia membayar tebusan dari harta Anshar"],
  "Quraisy menangkap Sa’d, mengikat tangan dan lehernya, lalu menyeretnya ke Makkah. Dua orang itu membalas jasa lama Sa’d.","hlm. 176")]},
# 9 Hijrah
{'s':[
 ("Apa yang terjadi pada Abu Bakar di Gua Tsaur ketika Nabi tidur di pangkuannya?",
  "Ia disengat hewan, tetapi menahan agar Nabi tidak terbangun",["Ia keluar gua untuk memeriksa apakah pengejar sudah dekat", "Ia ketiduran dan lupa berjaga di mulut gua sampai pagi"],
  "Abu Bakar tidak berani bergerak karena takut mengganggu tidur Rasulullah. Air matanya menetes ke wajah beliau.","hlm. 189"),
 ("Hadiah apa yang dijanjikan Quraisy bagi siapa pun yang membawa Nabi, hidup atau mati?",
  "Seratus ekor unta",["Seribu dinar emas", "Sebidang kebun korma"],
  "Quraisy menempatkan penjaga bersenjata di setiap jalur Makkah dan menyebar para pencari jejak, tetapi tidak menemukan beliau.","hlm. 190")],
 'd':[
 ("Berapa tokoh Quraisy yang ditunjuk untuk mengepung rumah Nabi pada malam hijrah?",
  "Sebelas orang tokoh, antara lain Abu Jahal dan Abu Lahab",["Tujuh orang tokoh, antara lain Abu Jahal dan Abu Sufyan", "Dua puluh orang tokoh, antara lain Utbah dan Syaibah", "Empat puluh orang tokoh dari seluruh kabilah Quraisy"],
  "Parlemen Makkah di Darun Nadwah menyetujui rencana jahat itu dengan suara bulat. Yang tampak tidur di tempat tidur beliau ternyata Ali.","hlm. 184–188"),
 ("Siapa Abdullah bin Uraiqith dalam perjalanan hijrah?",
  "Penunjuk jalan upahan yang masih musyrik tetapi dipercaya",["Pembantu Abu Bakar yang sudah lama masuk Islam dan ikut berhijrah", "Utusan As’ad bin Zurarah dari Anshar yang menjemput di Quba’", "Pemimpin Bani Khuza’ah yang ikut mengawal rombongan"],
  "Nabi dan Abu Bakar mengupahnya dan menyerahkan dua ekor unta kepadanya. Ia datang ke gua pada malam Senin, 16 September 622 M, lalu menempuh jalur pesisir yang jarang dilalui.","hlm. 190–191")]},
# 10 Madinah
{'s':[
 ("Apa langkah pertama yang dilakukan Rasulullah setelah menetap di Madinah?",
  "Membangun masjid",["Membangun benteng kota", "Mengirim pasukan ke Makkah"],
  "Tempat unta beliau berhenti dibeli dari dua anak yatim, lalu dibangun masjid. Beliau ikut memindahkan bata dan batu.","hlm. 210"),
 ("Sa’d bin Ar-Rabi’ menawarkan separuh hartanya kepada Abdurrahman bin Auf. Apa jawaban Abdurrahman?",
  "Ia meminta ditunjukkan pasar untuk berdagang",["Ia menolak dan meminta pulang ke Makkah", "Ia meminta dicarikan istri dari kalangan Anshar"],
  "Abdurrahman mendoakan keberkahan, lalu minta ditunjukkan pasar Bani Qainuqa’. Tak lama kemudian ia sudah memperoleh samin dan keju.","hlm. 212")],
 'd':[
 ("Apa tujuan mempersaudarakan Muhajirin dan Anshar, menurut buku?",
  "Mencairkan fanatisme Jahiliyah agar tidak ada yang dibela kecuali Islam",["Membentuk pasukan tetap untuk menyerang kafilah Quraisy", "Menyusun aturan pajak dan pembagian tanah di Madinah", "Mempercepat pembangunan masjid dan rumah di Madinah"],
  "Persaudaraan itu dijadikan ikatan nyata yang mempertautkan darah dan harta, bukan sekadar ucapan.","hlm. 212"),
 ("Bagaimana piagam Nabi dengan orang-orang Yahudi mengatur soal agama?",
  "Bagi Yahudi agama mereka dan bagi Muslim agama mereka",["Yahudi hanya boleh beribadah di dalam rumah mereka", "Yahudi diwajibkan masuk Islam dalam waktu satu tahun", "Yahudi dilarang berdagang dengan sesama penduduk Madinah"],
  "Piagam menjamin kebebasan beragama dan memutar kekayaan. Orang Yahudi menanggung nafkah mereka sendiri, dan Yatsrib dianggap kota suci bagi pihak-pihak perjanjian.","hlm. 218–219")]},
# 11 Badr
{'s':[
 ("Apa sasaran awal Rasulullah sebelum Perang Badr?",
  "Kafilah dagang Quraisy pimpinan Abu Sufyan",["Pasukan Quraisy pimpinan Abu Jahal di Makkah", "Benteng Yahudi Bani Qainuqa’ di Madinah"],
  "Kafilah membawa 1.000 unta dengan harta bernilai tak kurang dari 5.000 dinar emas, dikawal tak lebih dari 40 orang. Itu dipandang kesempatan emas memukul Quraisy.","hlm. 233"),
 ("Dua pemuda yang membunuh Abu Jahal adalah Mu’adz bin Amr Al-Jamuh dan…",
  "Mu’awwidz bin Afra’",["Sa’d bin Mu’adz", "Abdullah bin Mas’ud"],
  "Rasulullah menyerahkan rampasan Abu Jahal kepada Mu’adz. Abdullah bin Mas’ud kemudian menemukan Abu Jahal yang tinggal bernapas satu-satu.","hlm. 255–256")],
 'd':[
 ("Apa yang diusulkan Sa’d bin Mu’adz menjelang pertempuran Badr?",
  "Membuat tenda komando bagi Rasulullah lengkap dengan kendaraan",["Menunda pertempuran dan berunding lebih dulu dengan para pemuka Quraisy", "Menarik pasukan ke bukit dan menunggu serangan Quraisy", "Memecah pasukan menjadi dua barisan di dua sisi lembah"],
  "Tenda itu untuk memimpin sekaligus berjaga jika pasukan terdesak. Dengan kendaraan di sisinya, beliau bisa menyusul orang-orang yang tertinggal di belakang.","hlm. 243"),
 ("Siapa lawan tanding dalam tiga duel pembuka Badr?",
  "Ubaidah–Utbah, Hamzah–Syaibah, Ali–Al-Walid",["Ali–Utbah, Hamzah–Al-Walid, Ubaidah–Syaibah", "Ubaidah–Syaibah, Hamzah–Utbah, Ali–Al-Walid", "Hamzah–Abu Jahal, Ali–Utbah, Az-Zubair–Syaibah"],
  "Hamzah dan Ali menyelesaikan lawannya dengan cepat, lalu membantu Ubaidah yang kakinya putus. Ubaidah wafat di Ash-Shafra’ dalam perjalanan pulang. Catatan kaki buku menyebut riwayat lain tentang pasangan duel, tetapi uraian utama buku seperti jawaban ini (hlm. 249). Catatan kaki buku menyebut riwayat lain tentang pasangan duel, tetapi uraian utama buku seperti jawaban ini (hlm. 249). Catatan kaki buku menyebut riwayat lain tentang pasangan duel, tetapi uraian utama buku seperti jawaban ini (hlm. 249). Catatan kaki buku menyebut riwayat lain tentang pasangan duel, tetapi uraian utama buku seperti jawaban ini (hlm. 249).","hlm. 249")]},
# 12 Uhud
{'s':[
 ("Siapa yang membunuh Hamzah, singa Allah, dalam Perang Uhud?",
  "Wahsy bin Harb",["Amr bin Al-Ash", "Ikrimah bin Abu Jahal"],
  "Wahsy dulunya budak Jubair bin Muth’im dan menuturkan sendiri bagaimana ia membunuh Hamzah.","hlm. 307"),
 ("Bagian tubuh Nabi apa yang pecah ketika beliau terluka di Uhud?",
  "Gigi seri di dekat gigi taring",["Tulang rusuk sebelah kiri", "Tulang lengan kanan"],
  "Gigi seri beliau pecah dan kepala beliau terluka. Beliau bersabda, bagaimana mungkin suatu kaum beruntung jika melukai wajah Rasul-Nya.","hlm. 315")],
 'd':[
 ("Ketika tersiar kabar “Muhammad telah terbunuh”, apa kata seorang Anshar kepada pasukan yang meletakkan senjata?",
  "Jika Muhammad gugur, ia sudah sampai ke surga; berperanglah",["Mintalah perlindungan kepada Abdullah bin Ubay yang masih berada di Madinah", "Berdamailah dengan Abu Sufyan sebelum semua gugur", "Mundurlah ke Madinah dan bertahan di dalam benteng"],
  "Mental pasukan anjlok, dan sebagian bahkan berpikir mencari perlindungan kepada Abdullah bin Ubay. Seruan itu membangkitkan kembali semangat mereka.","hlm. 312–313"),
 ("Abu Dujanah menerima pedang Rasulullah. Tanda apa yang ia kenakan sebelum menerjang barisan musuh?",
  "Mengikat sorban merah di kepala, disebut ‘sorban kematian’",["Melepas baju besinya agar lebih ringan dan leluasa bergerak", "Menanggalkan perisainya dan menggenggam dua pedang", "Mengibarkan bendera hijau di ujung tombaknya"],
  "Az-Zubair yang meminta pedang itu lebih dulu merasa heran mengapa pedang diberikan kepada Abu Dujanah, lalu menguntitnya untuk melihat apa yang ia lakukan.","hlm. 306")]},
# 13 Ahzab dan Quraizhah
{'s':[
 ("Setelah Perang Khandaq, Jibril menyuruh Nabi bangkit menuju siapa?",
  "Bani Quraizhah",["Penduduk Khaibar", "Bani Qainuqa’"],
  "Pada waktu zhuhur, saat beliau mandi di rumah Ummu Salamah, Jibril berkata para malaikat tidak pernah meletakkan senjata dan menyuruh beliau berangkat ke Bani Quraizhah.","hlm. 372"),
 ("Siapa yang diangkat menjadi hakim untuk memutuskan perkara Bani Quraizhah?",
  "Sa’d bin Mu’adz",["Sa’d bin Ubadah", "Usaid bin Hudhair"],
  "Sa’d, yang terluka di lengannya sewaktu Perang Ahzab, dipanggil dengan menaiki keledai. Ia akhirnya wafat karena lukanya.","hlm. 375, 378")],
 'd':[
 ("Manakah yang BUKAN termasuk tiga usulan Ka’b bin Asad kepada Bani Quraizhah saat dikepung?",
  "Meminta bantuan Persia untuk mengusir kaum Muslimin",["Masuk Islam agar darah dan harta mereka aman", "Membunuh anak dan istri lalu berperang habis-habisan", "Menyerang Rasulullah dan sahabat pada hari Sabtu"],
  "Mereka menolak ketiga usulan itu, sehingga tidak ada pilihan selain pasrah pada keputusan Rasulullah.","hlm. 373"),
 ("Apa isyarat yang diberikan Abu Lubabah kepada Bani Quraizhah, dan apa akibatnya?",
  "Ia mengisyaratkan leher (tanda hukuman mati), lalu menyesal dan mengikat diri di tiang masjid",["Ia mengisyaratkan akan dibebaskan, lalu dihukum oleh Sa’d bin Mu’adz di kemudian hari", "Ia diam saja, lalu menyesal dan pergi meninggalkan Madinah menuju Makkah", "Ia membela mereka di hadapan Rasulullah, lalu ditegur dan diberi hukuman cambuk di depan masjid"],
  "Ia bersumpah tidak melepas tali itu sampai Rasulullah sendiri yang melepasnya. Beliau bersabda tidak akan melepasnya kecuali jika ia bertobat kepada Allah.","hlm. 373–374")]},
# 14 Hudaibiyah
{'s':[
 ("Tak seorang sahabat pun bangkit menyembelih kurban meski diperintah tiga kali. Siapa yang menyarankan Nabi melakukannya lebih dulu?",
  "Ummu Salamah, istri beliau",["Abu Bakar Ash-Shiddiq", "Utsman bin Affan"],
  "Atas saran Ummu Salamah, beliau keluar tanpa berbicara, menyembelih unta kurban, lalu meminta tukang cukur. Melihat itu para sahabat bangkit menyembelih dan bercukur.","hlm. 410"),
 ("Apa jawaban Nabi kepada Abu Jandal yang meminta agar tidak dikembalikan kepada kaum musyrik?",
  "Bersabarlah, Allah akan memberi jalan keluar; perjanjian tidak dilanggar",["Larilah ke bukit, kami akan melindungimu di sana", "Lawan saja Suhail, kami akan membelamu dengan pedang"],
  "Abu Jandal bin Suhail datang tertatih dengan kaki terbelenggu, tetapi Suhail menyeretnya untuk dikembalikan sesuai perjanjian. Umar menyemangatinya agar bersabar.","hlm. 409")],
 'd':[
 ("Dalam perjanjian itu, kabilah mana yang bergabung ke pihak Nabi dan mana ke pihak Quraisy?",
  "Khuza’ah ke pihak Nabi; Bani Bakr ke pihak Quraisy",["Khuza’ah ke pihak Quraisy; Bani Bakr ke pihak Nabi", "Keduanya netral sampai perjanjian berakhir", "Keduanya bergabung ke pihak Quraisy"],
  "Khuza’ah adalah sekutu Bani Hasyim sejak zaman Abdul Muththalib. Kelak Bani Bakr menyerang Khuza’ah, dan hal itu menjadi pemicu penaklukan Makkah.","hlm. 409, 478"),
 ("Setelah turun ayat tentang wanita mukminah yang berhijrah (Al-Mumtahanah), apa yang dilakukan Umar bin Al-Khaththab?",
  "Menceraikan dua istrinya yang masih kafir",["Menunda keputusan sampai umrah tahun berikutnya", "Menebus mereka dengan sepuluh ekor unta", "Mengembalikan mereka kepada suami mereka di Makkah"],
  "Dengan hukum ayat itu orang-orang Muslim menceraikan istri mereka yang kafir. Dua istri Umar kemudian dinikahi Mu’awiyah dan Shafwan bin Umayyah.","hlm. 411–412")]},
# 15 Surat ke raja dan Khaibar
{'s':[
 ("Apa cetakan pada cincin stempel perak yang dibuat Nabi untuk menyegel surat kepada para raja?",
  "Muhammad Rasul Allah",["Laa ilaaha illallah", "Bismillahirrahmanirrahim"],
  "Ada yang memberitahu bahwa para raja tidak akan menerima surat tanpa stempel. Surat-surat itu ditulis pada akhir tahun 6 H, sepulang dari Hudaibiyah.","hlm. 420"),
 ("Khaibar terletak sekitar berapa mil dari Madinah dan ke arah mana?",
  "Sekitar 60–80 mil ke arah utara",["Sekitar 60–80 mil ke arah selatan", "Sekitar 160–180 mil ke arah timur"],
  "Khaibar adalah kota besar dengan benteng dan kebun-kebun. Rasulullah menyerangnya sesudah gencatan senjata Hudaibiyah.","hlm. 440")],
 'd':[
 ("Apa yang dilakukan Zainab binti Al-Harits setelah Khaibar ditaklukkan?",
  "Menyodorkan domba panggang yang telah diberi racun kepada Nabi",["Masuk Islam di hadapan Nabi, lalu menyerahkan harta suaminya", "Menyembunyikan harta Bani Nadhir di dalam benteng Al-Qamush", "Menyerahkan kunci benteng Al-Qamush kepada Nabi tanpa perlawanan"],
  "Zainab, istri Sallam bin Misykam, mendatangi beliau sesudah beliau merasa tenang karena Khaibar telah dikuasai.","hlm. 456"),
 ("Bagaimana tanah Khaibar dibagi?",
  "Dibagi 3.600 bagian; separuh untuk Nabi dan kaum Muslimin, separuh untuk keperluan umum",["Dibagi 1.800 bagian sama rata hanya untuk peserta Perang Khaibar", "Dibagi 3.600 bagian; seluruhnya hanya untuk Nabi dan keluarga beliau", "Diserahkan kembali kepada penduduk Khaibar tanpa bagian untuk kaum Muslimin"],
  "Abdullah bin Rawahah menyusun perkiraan bagi hasilnya. Peserta Hudaibiyah (1.400 orang) juga mendapat bagian dari separuh yang terakhir.","hlm. 454")]},
# 16 Mu'tah dan Fathu Makkah
{'s':[
 ("Berapa kekuatan pasukan Muslimin di Mu’tah dan musuhnya?",
  "3.000 prajurit melawan sekitar 200.000",["10.000 prajurit melawan sekitar 20.000", "300 prajurit melawan sekitar 1.000"],
  "Pasukan Muslimin menghadapi Romawi dan sekutu Arab mereka, dan hanya dua belas orang yang gugur. Perang ini terjadi pada Jumadil Ula 8 H.","hlm. 469, 472, 475"),
 ("Ja’far bin Abu Thalib dijuluki At-Thayyar. Apa artinya?",
  "Penerbang, atau yang memiliki dua sayap",["Singa padang pasir yang tak kenal takut", "Pembawa panji pasukan di barisan depan"],
  "Ja’far gugur setelah kedua tangannya putus sambil mempertahankan bendera. Dikatakan Allah menganugerahinya dua sayap di surga. Ibnu Umar menghitung puluhan luka di tubuh depannya.","hlm. 472–473")],
 'd':[
 ("Ketika Abu Sufyan datang ke Madinah untuk memperbarui perjanjian, apa yang dilakukan putrinya, Ummu Habibah?",
  "Melipat lapik Rasulullah agar tidak diduduki ayahnya yang musyrik",["Memberinya hadiah dan bekal untuk dibawa pulang ke Makkah", "Mengusirnya dari rumah dan menutup pintu rapat-rapat", "Menyambutnya dan memintakan perlindungan kepada Nabi"],
  "Ummu Habibah berkata, lapik itu milik Rasulullah, sedangkan ayahnya musyrik lagi najis.","hlm. 481"),
 ("Di mana surat Hathib bin Abu Balta’ah kepada Quraisy ditemukan?",
  "Disembunyikan di gelungan rambut seorang wanita pembawanya",["Disembunyikan di dalam sepatu seorang pembawa pesan lelaki", "Diselipkan di bawah pelana unta milik seorang kurir", "Dititipkan kepada Abu Sufyan di rumahnya di Makkah"],
  "Surat itu membocorkan niat keberangkatan Rasulullah. Setelah didesak Ali dan rekannya, wanita itu melepas gelungan rambutnya dan mengeluarkan surat tersebut.","hlm. 484")]},
# 17 Hunain dan Tabuk
{'s':[
 ("Saat pasukan tercerai-berai di Hunain, siapa yang berseru, “Manakah orang yang berikrar di bawah pohon?”",
  "Al-Abbas bin Abdul Muththalib",["Abu Sufyan bin Al-Harits", "Umar bin Al-Khaththab"],
  "Al-Abbas memiliki suara paling lantang. Para sahabat menyahut, “Kami mendengar seruanmu,” dan kembali berkumpul.","hlm. 509"),
 ("Dalam pembagian harta rampasan Hunain di Ji’ranah, berapa bagian setiap prajurit yang tidak berkuda?",
  "4 ekor unta dan 40 domba",["12 ekor unta dan 120 domba", "1 ekor unta dan 10 domba"],
  "Penunggang kuda mendapat 12 ekor unta dan 120 domba.","hlm. 514")],
 'd':[
 ("Mengapa Nabi menunda pembagian rampasan Hunain selama sekitar 10 hari di Ji’ranah?",
  "Menunggu utusan Hawazin yang mungkin datang memohon amnesti dan harta mereka",["Menunggu selesainya perhitungan dan penimbangan seluruh harta rampasan perang", "Menunggu pasukan bantuan dari Makkah yang belum tiba", "Menunggu wahyu yang menetapkan cara pembagiannya"],
  "Karena tidak ada yang datang, beliau mulai membagi, antara lain untuk melunakkan hati para pemimpin kabilah dan pemuka Makkah yang baru masuk Islam.","hlm. 513–514"),
 ("Berapa orang utusan Hawazin yang datang dan siapa pemimpinnya?",
  "14 orang, dipimpin Zuhair bin Shurad",["30 orang, dipimpin Malik bin Auf", "7 orang, dipimpin Duraid bin Ash-Shimmah", "100 orang, dipimpin Abu Burqan"],
  "Mereka datang setelah semua rampasan dibagi untuk masuk Islam dan memohon dikembalikannya tawanan serta harta. Di antara mereka ada paman sepersusuan beliau, Abu Burqan.","hlm. 516")]},
# 18 Haji Wada' dan wafat
{'s':[
 ("Siapa yang menjadi imam shalat menggantikan Nabi selama beliau sakit?",
  "Abu Bakar Ash-Shiddiq",["Ali bin Abu Thalib", "Umar bin Al-Khaththab"],
  "Setelah tiga kali pingsan saat hendak menuju masjid, beliau mengutus orang memanggil Abu Bakar untuk mengimami. Sejak hari itu Abu Bakar yang mengimami.","hlm. 572"),
 ("Di mana Nabi dimakamkan?",
  "Di tempat beliau wafat, di bilik Aisyah",["Di pekuburan Baqi’ bersama para sahabat", "Di halaman Masjid Nabawi dekat mimbar"],
  "Abu Bakar meriwayatkan sabda beliau bahwa seorang nabi dikuburkan di tempat ia wafat. Abu Thalhah menggali liang lahat tepat di bawah tempat tidur beliau.","hlm. 574, 577")],
 'd':[
 ("Apa yang Nabi tetapkan tentang riba dalam khutbah Haji Wada’?",
  "Riba Jahiliyah dihapus; riba pertama yang dihapus adalah riba Al-Abbas",["Riba boleh dilanjutkan asalkan tidak berlipat ganda dan tidak memberatkan peminjam", "Riba dihapus semuanya, yang pertama dihapus riba Abu Sufyan bin Harb", "Riba dihapus kecuali pada perdagangan antar kabilah di musim haji"],
  "Beliau juga menghapus darah Jahiliyah; darah pertama yang dihapus adalah darah Ibnu Rabi’ah bin Al-Harits.","hlm. 563"),
 ("Mengapa Umar menangis ketika turun ayat, “Pada hari ini telah Kusempurnakan untuk kamu agamamu”?",
  "Karena setelah kesempurnaan itu hanya ada kekurangan",["Karena takut agama tidak akan sampai ke negeri Romawi", "Karena sedih kehilangan harta dalam perjalanan haji", "Karena mengira Quraisy akan kembali memerangi kaum Muslimin"],
  "Ayat Al-Maidah: 3 turun pada Haji Wada’. Umar tak kuasa menahan air matanya.","hlm. 564")]},
]
